package org.sleepwell.app;
import android.app.*;import android.os.*;import android.widget.*;import java.time.*;import java.util.concurrent.*;import java.util.function.Supplier;
/** Read-only milestones are recalculated from the pinned record source; never starts tracking. */
public final class RecordAchievementsActivity extends Activity {
 static Supplier<Instant> clock=Instant::now;private final ExecutorService worker=Executors.newSingleThreadExecutor(r->new Thread(r,"recorded-milestones"));private RecordAchievements data;private String error="";private boolean loading;private int generation;
 @Override public void onCreate(Bundle b){super.onCreate(b);RecordUi.review(this);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();}
 @Override protected void onResume(){super.onResume();load();}
 private void load(){int request=++generation;loading=true;error="";render();Records.Factory pinned=Records.factory;Supplier<Instant> time=clock;worker.execute(()->{try(Store s=pinned.open(getApplicationContext())){RecordAchievements result=RecordAchievementsReader.read(s,time.get().toEpochMilli());runOnUiThread(()->{if(isDestroyed()||request!=generation)return;data=result;loading=false;render();});}catch(Exception failure){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;loading=false;error=failure instanceof IllegalStateException?failure.getMessage():"Recorded progress is unavailable. Your records are kept.";if(error==null||error.isBlank())error="Recorded progress is unavailable. Your records are kept.";render();});}});}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Achievements",this::finish);Design.space(body,12);if(!error.isEmpty()){Design.text(body,error,16,500,Design.BROWN).setContentDescription("Achievements read error");Design.button(body,"Retry achievements",true,this::load);return;}if(data==null){Design.text(body,"Reading saved evidence…",15,400,Design.MUTED);return;}Design.text(body,data.count+" qualifying "+(data.count==1?"night":"nights"),30,700,Design.INK).setContentDescription("Qualifying recorded nights "+data.count);Design.space(body,6);Design.text(body,RecordUi.duration(data.millis)+" of valid sensor coverage on these recorded days",13,400,Design.MUTED);if(loading)Design.text(body,"Refreshing…",12,400,Design.MUTED);Design.space(body,20);
  milestone(body,1,"First recorded night");milestone(body,7,"Seven recorded nights");milestone(body,30,"Thirty recorded nights");Design.space(body,12);PlanActivity.detail(body,"shield","How progress is counted","At least 3 h of valid saved signal per recorded day",null,()->SleepPicker.message(this,"What qualifies?","Completed phone-motion or contactless recordings with at least 3 hours of valid saved sensor coverage per noon-to-noon recorded day. Pauses, marked-awake time, trims and overlaps are excluded. Nap-tagged, manual/Health Connect/unknown records, interrupted periods and clock-changed periods do not qualify. This measures recording coverage, not confirmed sleep."));Design.line(body);Design.text(body,"Calculated from current saved records. Editing or deleting a period can change progress. No streak or sleep-quality score is inferred.",12,400,Design.MUTED);
  if(data.count==0){Design.space(body,16);Design.text(body,"No qualifying nights yet",19,600,Design.INK);Design.text(body,"Missing or incomplete nights do not become zero-sleep days.",12,400,Design.MUTED);}else{RecordUi.heading(body,"Recent qualifying days");int from=Math.max(0,data.days.size()-7);for(int n=data.days.size()-1;n>=from;n--){RecordAchievements.Day day=data.days.get(n);PlanActivity.detail(body,"moon",day.date.toString(),null,RecordUi.duration(day.millis),()->startActivity(RecordUi.intent(this,RecordReportActivity.class).putExtra("record",day.record)));}}
  Design.space(body,12);Design.button(body,"Review saved records",true,()->startActivity(RecordUi.intent(this,HistoryActivity.class)));Design.button(body,"Refresh achievements",false,this::load).setEnabled(!loading);
 }
 private void milestone(LinearLayout body,int target,String title){LinearLayout row=Design.row(this);row.setGravity(android.view.Gravity.TOP);Design.pad(row,0,14);row.addView(new Design.Icon(this,data.reached(target)?"check":"moon",data.reached(target)?Design.BROWN:Design.MUTED),new LinearLayout.LayoutParams(Design.dp(this,26),Design.dp(this,26)));LinearLayout text=Design.col(this);text.setPadding(Design.dp(this,14),0,0,0);Design.text(text,title,17,600,Design.INK);Design.space(text,5);Design.text(text,data.reached(target)?"Reached in current records":data.progress(target)+" of "+target+" qualifying nights",13,400,Design.MUTED);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));row.setContentDescription(title+": "+data.progress(target)+" of "+target);body.addView(row);Design.line(body);}
 void awaitReaders(long timeout)throws Exception{if(worker.isShutdown()){if(!worker.awaitTermination(timeout,TimeUnit.MILLISECONDS))throw new TimeoutException("Achievements reader busy");}else worker.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
